version.transform:
(
  $count($) > 1 ? $throw("Visualization recieved more than one tag value. Please check your parameters transform.");

  $value := $coalesce([value, currentValue]);
  $high := $isNilOrEmpty(minimumValue)
    ? false
    : $value < minimumValue;
  $low := $isNilOrEmpty(maximumValue)
    ? false
    : $value > maximumValue;

  $color := $high or $low
              ? "#ff0000" 
              : "#00ff00";
  {
    "chart": {
      "caption": equipment.name,
      "subcaption": $coalesce([minimumValue, ""]) & "-" & $coalesce([maximumValue, ""]),
      "plotToolText": $value,
      "theme": "fusion",
      "showValue": "1",
      "valueFontColor": $color,
      "valueFontSize": 25
      },
      "colorRange": {
        "color": $not($isNilOrEmpty(minimumValue) or $isNilOrEmpty(maximumValue)) ? [
          {
              "minValue": (minimumValue - (maximumValue - minimumValue)/2),
              "maxValue": minimumValue,
              "code": "#FF0000"
          },
          {
              "minValue": minimumValue,
              "maxValue": maximumValue,
              "code": "#00FF00"
          },
          {
              "minValue": maximumValue,
              "maxValue": (maximumValue + (maximumValue - minimumValue)/2),
              "code": "#FF0000"
          }
        ] : [
          {
              "minValue": $value,
              "maxValue": $value,
              "code": "#505050"
          }
        ]
      },
      "dials": {
          "dial": [
              {
                  "value": $value,
                  "bgColor": "#FFFFFF"
              }
          ]
      }
  }
)
